# algebraic equations (name: expression of the other variables; L = line in subsystems.jl)
EQ = {
    "CNEL": lambda v: v.NEP * v.CNED,  # L141
    "NFCO2PP": lambda v: v.MNFCO2PP * (1 - exp(-(v.GDPP / 10))),  # L142
    "CO2NFIP": lambda v: (v.NFCO2PP / 1000) * v.POP * (1 - v.FCO2SCCS),  # L143
    "FCO2SCCS": lambda v: v.FCO2SCCS2022 + ramp(v.t, (v.GFCO2SCCS - v.FCO2SCCS2022) / v.IPP, 2022, 2022 + v.IPP),  # L144
    "CO2EI": lambda v: v.CO2EP + v.CO2NFIP,  # L145
    "CO2EP": lambda v: v.UFF * (v.TCO2PT / 1000) * (1 - v.FCO2SCCS),  # L146
    "CO2EMPP": lambda v: (v.CO2EI / v.POP) * 1000,  # L147
    "CCCSG": lambda v: v.CCCSt * v.ICCSC,  # L148
    "ICCSC": lambda v: v.FCO2SCCS * (v.CO2NFIP + v.CO2EP) / (1 - v.FCO2SCCS),  # L149
    "TCO2PT": lambda v: 2.8 * exp(v.ROCTCO2PT * (v.t - 1980)),  # L150
    "IEEPI": lambda v: v.EROCEPA2022 * 0 + step(v.ts, v.EROCEPA2022, 2022),  # L152
    "TPPUEBEE": lambda v: withlookup(v.GDPP, [(0.0, 0.0), (10.0, 4.0), (20.0, 7.0), (30.0, 9.0), (50.0, 12.0), (65.0, 13.0)]),  # L153
    "TPPUFFNEUBEE": lambda v: withlookup(v.GDPP, [(0.0, 0.3), (15.0, 2.0), (25.0, 3.1), (35.0, 4.0), (50.0, 5.0)]),  # L154
    "DEBNE": lambda v: (v.POP * v.TPPUEBEE * exp(-v.NIEE * (v.t - 1980))) / v.EEPI2022,  # L155
    "DFFNEUBNE": lambda v: (v.POP * v.TPPUFFNEUBEE * exp(-v.NIEE * (v.t - 1980))) / v.EEPI2022,  # L156
    "FNE": lambda v: v.FNE1980 + ramp(v.t, (v.FNE2022 - v.FNE1980) / 42, 1980, 2022) + ramp(v.t, (v.GFNE - v.FNE2022) / v.IPP, 2022, 2022 + v.IPP),  # L157
    "ERDNEFFFNE": lambda v: v.FNE * v.DFFNEUBNE,  # L158
    "CNE": lambda v: (v.ECRUNEFF / 1000) * v.ERDNEFFFNE,  # L159
    "EIDEFNE": lambda v: v.ERDNEFFFNE * v.EUEPRUNEFF,  # L160
    "DFFFNEU": lambda v: v.DFFNEUBNE - v.ERDNEFFFNE,  # L161
    "UFF": lambda v: v.DFFFNEU + v.FFE,  # L162
    "DE": lambda v: v.DEBNE + v.EIDEFNE,  # L163
    "DRES": lambda v: v.REFF1980 + ramp(v.t, (v.REFF2022 - v.REFF1980) / 42, 1980, 2022) + ramp(v.t, (v.GREF - v.REFF2022) / v.IPP, 2022, 2022 + v.IPP),  # L164
    "DSRE": lambda v: v.DE * v.DRES,  # L165
    "DREC": lambda v: v.DSRE / v.RCUT,  # L166
    "DRECC": lambda v: v.DREC - v.REC,  # L167
    "AREC": lambda v: max(0, (v.DRECC / v.RECT) + (v.DIREC)),  # L169
    "DIREC": lambda v: v.REC / v.LREC,  # L170
    "ASWC": lambda v: v.AREC,  # L171
    "NDSWC": lambda v: log(2) + log(v.ACSWCF1980 / v.SWC1980),  # L173
    "CISWC": lambda v: (1 - v.CRDSWC)**v.NDSWC,  # L174
    "CAPEXRED": lambda v: v.CAPEXRE1980 * v.CISWC,  # L175
    "CAPEXREG": lambda v: v.CAPEXRED * v.AREC,  # L176
    "OPEXREG": lambda v: v.OPEXRED * v.REP,  # L177
    "CRE": lambda v: v.CAPEXREG + v.OPEXREG,  # L178
    "CAPEXFEG": lambda v: v.CAPEXFED * v.AFEC,  # L179
    "OPEXFEG": lambda v: v.OPEXFED * v.FEP,  # L180
    "CFE": lambda v: v.CAPEXFEG + v.OPEXFEG,  # L181
    "CEL": lambda v: v.CFE + v.CRE + v.CNEL,  # L182
    "REP": lambda v: v.REC * v.RCUT,  # L183
    "GHMH2": lambda v: v.REP * v.FREH / v.KWEPKGH2,  # L184
    "GHMt": lambda v: v.GHMH2 * v.TPTH2,  # L185
    "RHP": lambda v: v.BEM + v.GHMt,  # L186
    "TWEPEJEE": lambda v: v.TWHPEJCE * v.EFPP,  # L187
    "IIASAREP": lambda v: v.REP / v.TWEPEJEE + v.RHP / v.MTPEJCE,  # L188
    "FTWEPMt": lambda v: v.TWEPEJEE / v.MTPEJCE,  # L189
    "IIASAFEP": lambda v: v.UFF / v.MTPEJCE,  # L190
    "LCEP": lambda v: v.REP + v.NEP,  # L191
    "DFE": lambda v: max(0, v.DE - v.LCEP),  # L192
    "DFEC": lambda v: v.DFE / v.EKHPY,  # L193
    "DFECC": lambda v: (v.DFEC - v.FEC) / v.FECCT + v.DIFEC,  # L194
    "AFEC": lambda v: max(0, v.DFECC),  # L195
    "LFEC": lambda v: v.NLFEC * v.FCUTLOFC,  # L197
    "DIFEC": lambda v: v.FEC / v.LFEC,  # L198
    "FCUT": lambda v: v.DFE / v.FEC,  # L199
    "FCUTLOFC": lambda v: 1 + v.sFCUTLOFC * ((v.FCUT / v.EKHPY) - 1),  # L200
    "FEP": lambda v: v.FEC * v.FCUT,  # L201
    "NC": lambda v: withlookup(v.t, [(1980.0, 75.0), (2000.0, 310.0), (2020.0, 310.0), (2098.9, 310.0)]),  # L202
    "NEP": lambda v: v.NC * v.NCUT,  # L203
    "EP": lambda v: v.FEP + v.LCEP,  # L204
    "ELB": lambda v: v.EP / v.DE,  # L205
    "FFPNE": lambda v: (v.FEP + v.NEP) / v.EP,  # L206
    "EU": lambda v: v.DFFFNEU + v.EP / v.FTWEPMt + v.RHP,  # L207
    "EUPP": lambda v: v.EU / v.POP,  # L208
    "FFE": lambda v: v.FEP / v.FTWEPMt,  # L209
    "TCEG": lambda v: (v.DEBNE * v.TCE / 1000) * v.AFMCM,  # L210
    "TCFFFNEUG": lambda v: (v.DFFNEUBNE * v.TCFFFNEU / 1000) * v.AFMCM,  # L211
    "CFFFNEU": lambda v: (v.DFFFNEU * v.TCFFFNEU) / 1000,  # L212
    "CG": lambda v: v.EP * v.TC,  # L213
    "TGC": lambda v: v.DEBNE * v.TC,  # L214
    "TCEN": lambda v: v.TCEG + v.TCFFFNEUG + v.TGC,  # L215
    "TCENSGDP": lambda v: v.TCEN / v.GDP,  # L216
    "CE": lambda v: v.CFFFNEU + v.CEL + v.CG + v.CNE + v.CCCSG + v.CAC,  # L217
    "RECTEC": lambda v: v.CE / v.TCEN,  # L218
    "CESGDP": lambda v: v.CE / v.GDP,  # L219
    "ECETSGDP": lambda v: (((v.CE - v.TCEN) / v.GDP) if (v.ts > 2022) else (0)),  # L220
}

# derivatives of the states (smooth!(x, input, T) is D(x) = (input - x) / T)
DER = {
    "EEPI2022": lambda v: v.IEEPI,  # L151
    "REC": lambda v: v.AREC - v.DIREC,  # L168
    "ACSWCF1980": lambda v: v.ASWC,  # L172
    "FEC": lambda v: v.AFEC - v.DIFEC,  # L196
}


class EnergySector(E4ASector):
    name = "e4a_energy"
    SECTOR_KEY = "energy"
    STATE_NAMES = STATE_NAMES
    PARAMS = PARAMS
    PARAMS_GL = PARAMS_GL
    PARAM_EXPR = PARAM_EXPR
    INITS = INITS
    STATE_INIT = STATE_INIT
    EQ = EQ
    DER = DER
    INPUT_NAMES = INPUT_NAMES
    inputs = {n: UNITS[n] for n in INPUT_NAMES}
    outputs = {n: UNITS[n] for n in list(EQ) + list(STATE_NAMES)}


SECTOR_CLASS = EnergySector
